Here’s the updated list of available file‑system tools you can use:

```json
{
  "cat": {
    "description": "Display the contents of a file of any extension from the current directory.",
    "parameters": {
      "file_name": "string"
    }
  },
  "cp": {
    "description": "Copy a file or directory from one location to another. If the destination is a directory, the source file or directory will be copied into the destination directory. Both source and destination must be local to the current directory.",
    "parameters": {
      "source": "string",
      "destination": "string"
    }
  },
  "diff": {
    "description": "Compare two files of any extension line by line at the current directory.",
    "parameters": {
      "file_name1": "string",
      "file_name2": "string"
    }
  },
  "du": {
    "description": "Estimate the disk usage of a directory and its contents.",
    "parameters": {
      "human_readable": "boolean (default: false)"
    }
  },
  "echo": {
    "description": "Write content to a file at current directory or display it in the terminal.",
    "parameters": {
      "content": "string",
      "file_name": "string (default: None)"
    }
  },
  "find": {
    "description": "Find any file or directories under a specific path that contain a name in its file name. This method performs a recursive search through all subdirectories of the given path.",
    "parameters": {
      "path": "string (default: \".\")",
      "name": "string (default: \"None\")"
    }
  },
  "grep": {
    "description": "Search for lines in a file of any extension at current directory that contain the specified pattern.",
    "parameters": {
      "file_name": "string",
      "pattern": "string"
    }
  },
  "ls": {
    "description": "List the contents of the current directory.",
    "parameters": {
      "a": "boolean (default: false)"
    }
  },
  "mkdir": {
    "description": "Create a new directory in the current directory.",
    "parameters": {
      "dir_name": "string"
    }
  },
  "mv": {
    "description": "Move a file or directory from one location to another.",
    "parameters": {
      "source": "string",
      "destination": "string"
    }
  },
  "pwd": {
    "description": "Return the current working directory path."
  },
  "rm": {
    "description": "Remove a file or directory.",
    "parameters": {
      "file_name": "string"
    }
  },
  "rmdir": {
    "description": "Remove a directory at current directory.",
    "parameters": {
      "dir_name": "string"
    }
  },
  "sort": {
    "description": "Sort the contents of a file line by line.",
    "parameters": {
      "file_name": "string"
    }
  },
  "tail": {
    "description": "Display the last part of a file of any extension.",
    "parameters": {
      "file_name": "string",
      "lines": "number (default: 10)"
    }
  },
  "touch": {
    "description": "Create a new file of any extension in the current directory.",
    "parameters": {
      "file_name": "string"
    }
  },
  "wc": {
    "description": "Count the number of lines, words, and characters in a file of any extension from current directory.",
    "parameters": {
      "file_name": "string",
      "mode": "string (default: \"l\")"
    }
  },
  "cd": {
    "description": "Change the current working directory to the specified folder. You can only change one folder level at a time.",
    "parameters": {
      "folder": "string"
    }
  }
}
```

